/// <summary>
/// Returns true when all entries share the same normalized failure reason.
/// Normalization strips leading/trailing whitespace and collapses consecutive
/// whitespace so cosmetic output differences don't mask identical root causes.
/// </summary>
private static bool VerifySignaturesAreIdentical(List<(string Reason, string OutputPath)> signatures)
{
    if (signatures.Count == 0) return false;
    var first = NormalizeReason(signatures[0].Reason);
    for (var i = 1; i < signatures.Count; i++)
    {
        if (!string.Equals(first, NormalizeReason(signatures[i].Reason), StringComparison.Ordinal))
            return false;
    }
    return true;
}

private static string NormalizeReason(string reason)
{
    return string.Join(" ", reason.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
}

